export class DataGridError extends Error{constructor(code,message,details={}){super(message);this.name='DataGridError';this.code=code;this.details=details;}}
const fail=(c,m,d={})=>{throw new DataGridError(c,m,d)};const missing=v=>v===null||v===undefined||Number.isNaN(v);
function cmp(a,b,type){if(missing(a)&&missing(b))return 0;if(missing(a))return 1;if(missing(b))return -1;if(type==='number'||type==='date')return (+a)-(+b);if(type==='boolean')return Number(a)-Number(b);return String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'});}
export function prepareDataGrid(input={}){if(!Array.isArray(input.rows))fail('GRID_ROWS','rows must be array');const rows=input.rows.map((r,i)=>Object.freeze({...r,__rowIndex:i}));const cols=(input.columns??Object.keys(rows[0]??{}).filter(k=>!k.startsWith('__'))).map((c,i)=>typeof c==='string'?{key:c,label:c,type:'text'}:{...c,key:String(c.key),label:String(c.label??c.key),type:c.type??'text'});if(new Set(cols.map(c=>c.key)).size!==cols.length)fail('GRID_COLUMNS','column keys must be unique');let view=rows.slice();const filter=String(input.filter??'').trim().toLowerCase();if(filter)view=view.filter(r=>cols.some(c=>String(r[c.key]??'').toLowerCase().includes(filter)));if(input.sort?.key){const c=cols.find(c=>c.key===input.sort.key);if(!c)fail('GRID_SORT','unknown sort column');const dir=input.sort.direction==='desc'?-1:1;view.sort((a,b)=>{const av=a[c.key],bv=b[c.key];if(missing(av)&&missing(bv))return a.__rowIndex-b.__rowIndex;if(missing(av))return 1;if(missing(bv))return -1;const z=cmp(av,bv,c.type);return z?z*dir:a.__rowIndex-b.__rowIndex;});}
 return Object.freeze({columns:Object.freeze(cols.map(Object.freeze)),rows:Object.freeze(view),rowCount:view.length,sourceRowCount:rows.length,filter,sort:input.sort??null});}
export function rowAt(model,index){return index>=0&&index<model.rows.length?model.rows[index]:null;}
export function gridVirtualWindow(rowCount,scrollTop,viewportHeight,rowHeight=32,overscan=6){const count=Math.max(0,Math.trunc(rowCount)),rh=Math.max(1,+rowHeight||32),vh=Math.max(0,+viewportHeight||0),maxStart=Math.max(0,count-1),raw=Math.floor(Math.max(0,+scrollTop||0)/rh),visible=Math.ceil(vh/rh),start=count?Math.min(maxStart,Math.max(0,raw-overscan)):0,end=count?Math.min(count,start+visible+overscan*2):0;return Object.freeze({start,end,offsetY:start*rh,totalHeight:count*rh,count:Math.max(0,end-start)});}
